SELECT health_environment_profile::jsonb->'environment'->>'water_quality_index', 
       REGEXP_REPLACE(health_environment_profile::jsonb->'environment'->>'water_quality_index', '[^0-9.]', '') as wq_num
FROM environmentandhealth LIMIT 5;

SELECT health_environment_profile::jsonb->'environment'->>'water_quality_index',
       SPLIT_PART(health_environment_profile::jsonb->'environment'->>'water_quality_index', ' ', 1)::numeric as wq_num
FROM environmentandhealth LIMIT 5;
